:root{
  --bg:#f2f0e8;
  --panel:#fffdf7;
  --panel-2:#f8f5ec;
  --ink:#17201c;
  --muted:#69736d;
  --line:#e1ddd1;
  --line-strong:#c8c3b4;
  --accent:#0c6b55;
  --accent-ink:#084d3d;
  --accent-soft:#d9ece4;
  --watch:#8a5a00;
  --watch-soft:#f8ebc9;
  --pos:#16734a;
  --neg:#b23a32;
  --warm:#a85a1c;
  --radius:10px;
  --sans:system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,"Noto Sans",sans-serif;
  --mono:ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,"Liberation Mono","Courier New",monospace;
}
*{box-sizing:border-box}
html,body{margin:0;padding:0}
body{background:var(--bg);color:var(--ink);font-family:var(--sans);line-height:1.5;font-size:15px}
a{color:var(--accent-ink);text-decoration:none}
a:hover{text-decoration:underline}
.hidden{display:none!important}
.skip{position:absolute;left:-999px;top:0;background:var(--panel);padding:8px 12px;border:1px solid var(--line);z-index:50}
.skip:focus{left:8px;top:8px}
.topbar{position:sticky;top:0;z-index:30;display:flex;gap:18px;justify-content:space-between;align-items:center;padding:12px 22px;background:rgba(242,240,232,.94);backdrop-filter:blur(10px);border-bottom:1px solid var(--line)}
.brand{display:flex;gap:12px;align-items:center;min-width:0}
.brand-mark{width:12px;height:38px;border-radius:3px;background:linear-gradient(180deg,var(--accent),#0a4a3a);flex:none}
h1{margin:0;font-size:19px;line-height:1.15;letter-spacing:-.01em;font-weight:700}
.subtitle{margin:2px 0 0;color:var(--muted);font-size:12.5px}
.meta{display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end;font-size:12px;color:var(--muted)}
.pill{padding:4px 9px;border:1px solid var(--line);border-radius:999px;background:var(--panel);white-space:nowrap}
main{max-width:1300px;margin:0 auto;padding:18px 22px 34px}
.panel{background:var(--panel);border:1px solid var(--line);border-radius:var(--radius);box-shadow:0 1px 2px rgba(23,32,28,.05),0 10px 30px rgba(23,32,28,.05)}

.controls{display:grid;grid-template-columns:minmax(220px,1.6fr) repeat(2,minmax(150px,1fr)) auto;gap:12px;padding:14px;border-bottom:1px solid var(--line);align-items:end}
.field{display:flex;flex-direction:column;gap:5px;min-width:0}
.field>span{font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);font-weight:650}
input,select,button{font:inherit;color:var(--ink);background:var(--panel-2);border:1px solid var(--line-strong);border-radius:8px;padding:9px 10px}
input::placeholder{color:#9aa29c}
input:focus,select:focus,button:focus,a:focus{outline:2px solid var(--accent);outline-offset:2px}
button{cursor:pointer}
button:hover{border-color:var(--accent)}
.toggle{display:flex;align-items:center;gap:10px;padding:8px 12px;border:1px solid var(--line-strong);border-radius:8px;background:var(--panel-2);cursor:pointer;min-width:190px}
.toggle input{width:17px;height:17px;margin:0;accent-color:var(--accent);flex:none}
.toggle-text{display:flex;flex-direction:column;line-height:1.25}
.toggle-text strong{font-size:13px;font-weight:650}
.toggle-text small{font-size:11px;color:var(--muted)}

.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;padding:0 14px 14px}
.stat{background:var(--panel-2);border:1px solid var(--line);border-top:3px solid var(--accent);border-radius:8px;padding:10px 12px;min-width:0}
.stat .k{font-size:10.5px;letter-spacing:.07em;text-transform:uppercase;color:var(--muted);font-weight:650;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.stat .v{font-family:var(--mono);font-variant-numeric:tabular-nums;font-size:21px;font-weight:600;letter-spacing:-.02em;margin-top:2px;white-space:nowrap}
.stat .s{font-size:11.5px;color:var(--muted);margin-top:1px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}

.model-note{display:flex;gap:8px;align-items:baseline;padding:9px 14px;border-bottom:1px solid var(--line);background:#f7f4ea;font-size:11.5px;color:#55615a;line-height:1.45}
.model-note strong{flex:none;font-size:10px;letter-spacing:.07em;text-transform:uppercase;color:var(--accent-ink)}
.table-wrap{overflow:auto;max-height:calc(100vh - 382px);min-height:220px}
table{width:100%;border-collapse:separate;border-spacing:0;font-size:13.5px}
thead th{position:sticky;top:0;z-index:5;background:var(--panel);text-align:left;padding:9px 10px;border-bottom:1px solid var(--line-strong);color:var(--muted);font-weight:600;white-space:nowrap}
thead th.c-num{text-align:right}
.th-sort{display:inline-flex;align-items:center;gap:4px;background:none;border:0;padding:2px 0;color:inherit;font-size:11.5px;letter-spacing:.05em;text-transform:uppercase;font-weight:700;border-radius:3px}
.th-sort:hover{color:var(--ink);border-color:transparent}
.th-sort .arrow{font-size:9px;color:var(--accent);min-width:9px}
tbody td{padding:10px;border-bottom:1px solid #ece8dc;vertical-align:middle}
tbody tr{transition:background .12s ease}
tbody tr:hover{background:#f4f1e6}
tbody tr:focus-within{background:#eef4ee}
tbody tr:last-child td{border-bottom:0}
.num{font-family:var(--mono);font-variant-numeric:tabular-nums;white-space:nowrap}
td.c-num,th.c-num{text-align:right}
.c-rank{width:58px}
.rank{font-weight:700;color:var(--accent);font-size:13px}
.proto{display:flex;align-items:center;gap:7px;flex-wrap:wrap}
.name{font-weight:650;color:var(--ink);font-size:14px}
.name:hover{color:var(--accent-ink)}
.sub{color:var(--muted);font-size:11.5px;margin-top:1px}
.chip{display:inline-block;padding:2px 7px;border-radius:999px;border:1px solid var(--line);font-size:10.5px;line-height:1.4;color:var(--muted);background:var(--panel-2);white-space:nowrap}
.chip.cat{font-size:10.5px;letter-spacing:.02em;background:#eef1ec;border-color:#d8ddd4;color:#4c5a52}
.chip.watch{background:var(--watch-soft);border-color:#e7cf95;color:var(--watch);font-weight:750;letter-spacing:.06em}
.chip.token{background:var(--accent-soft);border-color:#b9dbcd;color:var(--accent-ink)}
.value{display:flex;flex-direction:column;align-items:flex-end;gap:4px}
.vbar{display:block;width:100%;max-width:120px;height:4px;background:#eae6da;border-radius:2px;overflow:hidden}
.vbar i{display:block;height:100%;background:linear-gradient(90deg,#1d8c6f,var(--accent));border-radius:2px}
.pos{color:var(--pos)}.neg{color:var(--neg)}.muted{color:var(--muted)}

.empty{padding:54px 20px;text-align:center;color:var(--muted)}
.empty svg{width:64px;height:64px;color:#aab3ab;margin-bottom:8px}
.empty h2{margin:0 0 4px;color:var(--ink);font-size:19px}
.empty p{margin:0 0 16px;font-size:14px}
.btn{display:inline-block;padding:9px 14px;border-radius:8px;background:var(--accent);border:1px solid var(--accent);color:#fffdf7;font-weight:650;font-size:13.5px}
.btn:hover{background:var(--accent-ink);text-decoration:none}

.method{border-top:1px solid var(--line);background:var(--panel-2);border-radius:0 0 var(--radius) var(--radius)}
.method summary{display:flex;align-items:center;gap:8px;padding:13px 16px;cursor:pointer;list-style:none;font-size:13px;font-weight:650;color:var(--ink)}
.method summary::-webkit-details-marker{display:none}
.method summary::before{content:"+";display:inline-flex;align-items:center;justify-content:center;width:18px;height:18px;border:1px solid var(--line-strong);border-radius:4px;font-family:var(--mono);font-size:12px;color:var(--accent-ink);background:var(--panel)}
.method[open] summary::before{content:"−"}
.method summary span{margin-left:auto;font-size:11px;font-weight:500;color:var(--muted)}
.method-body{padding:0 16px 16px}
.method h2{margin:0 0 10px;font-size:15px;letter-spacing:-.01em}
.method-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
.method h3{margin:0 0 4px;font-size:12px;text-transform:uppercase;letter-spacing:.06em;color:var(--accent-ink)}
.method p{margin:0 0 7px;font-size:12.5px;color:#4f5a54;line-height:1.5}
.method .disclaimer{margin:12px 0 0;padding-top:10px;border-top:1px solid var(--line);font-size:12px;color:var(--muted)}

.back{display:inline-flex;align-items:center;gap:6px;margin-bottom:12px;font-size:13px;font-weight:650}
.detail-head{display:flex;align-items:center;gap:16px;padding:16px;margin-bottom:12px}
.rank-badge{width:56px;height:56px;border-radius:10px;background:var(--accent-soft);color:var(--accent-ink);display:flex;align-items:center;justify-content:center;font-family:var(--mono);font-size:17px;font-weight:700;flex:none}
.detail-head .grow{min-width:0;flex:1}
