.card .lead{margin:0 0 10px;font-size:12.5px;color:var(--muted)}
.kv{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:9px;margin-top:10px}
.kv .item{background:var(--panel-2);border:1px solid var(--line);border-radius:8px;padding:8px 10px}
.kv .k{font-size:10.5px;letter-spacing:.05em;text-transform:uppercase;color:var(--muted);font-weight:650}
