.factor{background:var(--panel-2);border:1px solid var(--line);border-radius:8px;padding:9px 10px}
.factor .k{font-size:10.5px;letter-spacing:.05em;text-transform:uppercase;color:var(--muted);font-weight:650}
.factor .v{font-family:var(--mono);font-size:16px;font-weight:700;margin-top:2px}
