.sym{font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.03em;padding:2px 5px;border-radius:4px;background:#e8ede7;color:#3d5147;min-width:38px;text-align:center}
.pname{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.pmult{font-weight:700;color:var(--accent-ink)}
.pmcap{font-size:11px;color:var(--muted)}
.callout{margin-top:10px;padding:9px 11px;border:1px solid #cfe2d8;border-radius:7px;background:#f1f8f4;font-size:12px;color:#31443c;line-height:1.5}
.callout.warn{border-color:#ead6a8;background:#fdf6e5;color:#5c4716}
.callout strong{display:block;font-size:11px;letter-spacing:.05em;text-transform:uppercase;margin-bottom:2px}

.steps{list-style:none;margin:10px 0 0;padding:0;display:grid;gap:9px}
.step{display:grid;grid-template-columns:26px minmax(0,1fr);gap:11px;padding:11px;border:1px solid var(--line);border-radius:8px;background:var(--panel-2)}
.step-n{width:26px;height:26px;border-radius:50%;background:var(--accent-soft);color:var(--accent-ink);display:flex;align-items:center;justify-content:center;font-family:var(--mono);font-weight:700;font-size:12px}
.step-body{font-size:13px;line-height:1.55}
.step-chips{display:flex;flex-wrap:wrap;gap:6px;margin-top:6px}
.chip.cost{background:#eef4e4;border-color:#d3dfbf;color:#3f5620}
.chip.time{background:#eaf1f7;border-color:#cad9e6;color:#2c4c68}
.foot{max-width:1300px;margin:0 auto;padding:0 22px 26px;color:var(--muted);font-size:11.5px}

@media (max-width:1000px){
  .controls{grid-template-columns:1fr 1fr}
  .toggle{grid-column:span 2}
  .stats{grid-template-columns:1fr 1fr}
  .method-grid{grid-template-columns:1fr}
  .span-7,.span-5{grid-column:span 12}
  .table-wrap{max-height:none}
  .head-value{text-align:left}
  .detail-head{flex-wrap:wrap}
}
@media (max-width:620px){
  .topbar{padding:10px 14px}
  main{padding:12px 14px 24px}
  h1{font-size:17px}
  .subtitle{display:none}
  .controls{grid-template-columns:1fr;padding:12px}
  .toggle{grid-column:auto}
  .stats{grid-template-columns:1fr 1fr;padding:0 12px 12px}
  .stat .v{font-size:18px}
  .factors{grid-template-columns:1fr}
  .peers li{grid-template-columns:auto minmax(0,1fr) auto}
  .pmcap{display:none}
}
